  ["ff00b65dab470201"] = { "Voglio fare un acquisto.", "." },
  ["ff05591d594254a9"] = { "Salute, {class}. Fai attenzione mentre viaggi verso est, verso la ⟦The Bulwark=Granbarricata⟧. Recenti rapporti di ricognizione indicano un aumento dell'attività del Flagello in quella zona, perciò sii prudente.", "." },
  ["ff09f93da2768327"] = { "Baciami.", "." },
  ["ff0ee181a9ec2557"] = { "Dov'è l'anziana Totem Fulgido?", "." },
  ["ff0fc61cde4b7a44"] = { "Da qui faccio prima a viaggiare per conto mio, {name}. Raggiungi ⟦Jessir Moonbow=Jessir Arcoluna⟧ vicino a ⟦Ashenvale=Valtetra⟧. Dovrebbe essere con i druidi della ⟦Emerald Circle=Fede di Smeraldo⟧. Ti dirà lei cosa fare. Grazie di tutto il tuo aiuto!", "." },
  ["ff22287d83f87996"] = { "Uff! Credo di aver mangiato troppo. Devo allentare la cintura di qualche buco.", "." },
  ["ff2358fd57238ad3"] = { "No, il fossile non l'ho lasciato qui dietro!", "." },
  ["ff2485b95203d998"] = { "Non posso addestrarti, giovane.", "." },
  ["ff27de9f7ec11cee"] = { "Il rogo dell'Uomo di Paglia inizierà fra quindici minuti! Vieni alla festa, appena a ovest di ⟦Undercity=Sepulcra⟧, e celebra la Veglia delle Ombre e la nostra liberazione dal Flagello!", "." },
  ["ff2d4d26f84284d8"] = { "Molti considerano il bastone un'arma inferiore. Sfido chiunque la pensi così a mettere alla prova la sua forza contro il mio bastone.", "." },
  ["ff36d45a60800ef1"] = { "Interessante... continua, John.", "." },
  ["ff4bccc32175dabd"] = { "%s inizia il rituale.", "." },
  ["ff4eb55eba0beeaa"] = { "Sono paziente. Paziente ed eterno come un'antica pietra kank di Draenor. Gli uomini-pesce non oltrepasseranno i nostri confini, non finché sarò in piedi. Se avessimo un esercito ai nostri ordini, ripulirei questo mondo e tutti gli altri dalla loro presenza. Sento l'odio ribollire solo a parlarne.", "." },
  ["ff54dc6a6bdc970f"] = { "Ehi, Rocknot!", "." },
  ["ff56d459547fc19c"] = { "Ce l'hai il sapta, <fratello/sorella>?\n\nConosco un altro che ha avuto problemi dopo aver sconfitto lo spirito dell'acqua corrotto: pare che abbia aspettato troppo e sia uscito dal mondo degli spiriti troppo presto pe' i suoi gusti. Non vorrei che succedesse a qualcun altro, quindi aspetterò qui ancora un po' per essere sicuro che nessun altro abbia bisogno del mio aiuto.", "." },
  ["ff597f7b055e1b8b"] = { "Beccati questa, arpia rognosa! Hyaa!", "." },
  ["ff5e508221e424c3"] = { "Questo frutteto ora è sterile e senza vita come il mio guscio putrescente. Un tempo questi alberi erano carichi di frutti, ora c'è solo marciume.", "." },
  ["ff61af55b116b28e"] = { "Pattuglierò il passo che sale alla ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧. Dammi solo il segnale e prenderò il volo, comandante.", "." },
  ["ff636565097a5992"] = { "Il ⟦First Aid=Primo Soccorso⟧ non sostituisce le cure di un sacerdote, ma nel momento del bisogno torna utile. Ti consiglio di andare a parlare con Thamner nella ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ e imparare quello che puoi.", "." },
  ["ff667c2486460146"] = { "Sì, <fratello/sorella>, come posso aiutarti?", "." },
  ["ff6a401012a6ffb0"] = { "Va' a Orgrimmar, nella ⟦Valley of Honor=Valle dell'Onore⟧. Lì vive con il marito e le due figlie. Sono tutti fabbri di grande abilità, ma gli spiriti mi dicono che sarà lei a guidare meglio il tuo apprendimento.", "." },
  ["ff750d46edfaf12e"] = { "Cosa pensi di ottenere con questo, <sciocco/sciocca>? Già ora gli eserciti dei ⟦Blackrock=Roccianera⟧ si preparano a distruggere il tuo mondo.", "." },
  ["ff75192fa6cb694c"] = { "Come desideri, Vaelan.", "." },
  ["ff7aa25cb4fe9951"] = { "Tra i troll Zandalari l'onore si guadagna, {name}. Con l'onore arriva la ricompensa: amicizia, alleanza...\n\nDammi il talismano, così che io possa accrescerne il potere.", "." },
  ["ff8028befb6c97aa"] = { "Anni di tecniche di allevamento di qualità e tante cure mi concedono il privilegio di mostrarti questi cavalli! Prego, prenditi tutto il tempo che serve per sceglierne uno come cavalcatura. Un cavallo è un compagno per la vita, amico. Non accontentarti: prendi il tuo destriero qui, oggi stesso!", "." },
  ["ff80585c5d35df29"] = { "Profanatori!", "." },
  ["ff829e37c4c0c8c0"] = { "Ah, molto bene. Mi hai convinto: sei <un/una> <allievo/allieva> <degno/degna>. Ora il tuo addestramento con me può cominciare...", "." },
  ["ff85bc0e1ef69f4e"] = { "Divertiti alla ⟦Booty Bay=Baia del Bottino⟧, {name}!", "." },
  ["ff887607b7554095"] = { "Dove andare? Cosa fare? Tante scelte, e tutte finiscono nel dolore, finiscono nella morte.", "." },
  ["ff89e8ce3c552c28"] = { "Pulite questo posto! Non vivremo in un simile squallore.", "." },
  ["ff9624548e072fc1"] = { "Ah, finalmente! Che bello sarà liberarsi di questi barili.", "." },
  ["ff9bdec4fdeec5ee"] = { "Cosa sono i Paragons of Power?", "." },
  ["ffa223922dcb99eb"] = { "Salute, <avventuriero/avventuriera>.", "." },
  ["ffa48fb8ad4bc95f"] = { "Maestro, quando la vediamo la Torre dei Maghi scintillante?", "." },
  ["ffb0656c8dac3f04"] = { "Ottima domanda! Qui alla fiera abbiamo molte cose in vendita. Se ti interessano cibo e bevande, va' allo stand di Stamp e Sylannia. La mia preferita è la ⟦Darkmoon Special Reserve=Riserva Speciale di Lunacupa⟧.\n\nSe preferisci comprare qualcosa di più esotico, Lhara potrebbe avere proprio quello che fa per te. È specializzata in rarità da tutto il mondo.\n\nE poi c'è Flik, che corre qui intorno da qualche parte. Se riesci ad acchiapparlo, vende palle da lanciare e rane da tenere come animaletti.", "." },
  ["ffb578400787fbef"] = { "{name} conquista la fucina! Se nessuno la contende, l'⟦Horde=Orda⟧ la controllerà fra 1 minuto!", "." },
  ["ffb849b10e3be4fe"] = { "Mi godrò un mondo a far fuori questi narcisi a bocca aperta!", "." },
  ["ffbdacee38d89672"] = { "Mmm, credo di poter prendere un altro allievo. Beh, non startene lì impalat<o/a>. Dimmi cosa vuoi imparare.", "." },
  ["ffbec7606593f345"] = { "Una volta ho conosciuto qualcuno come te... Si chiamava Vol'jin. Sei di una razza rara, amico mio.", "." },
  ["ffc3fb864b8521ce"] = { "YAW! Ehm, in prima linea, tu!", "." },
  ["ffd022f8fce0edb0"] = { "Fuggire non vi servirà, mortali!", "." },
