  ["ffd919d7efae2fa3"] = { "Grrrr! Idioti!", "." },
  ["ffe7673d7424501f"] = { "Ciao, {class}! Con la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧ ormai vicina, i preparativi qui sono in pieno svolgimento. Io mi occupo della raccolta di Cuoio Spesso. È una bella giornata per raccogliere Cuoio Spesso, non trovi? Ho qui le mie pile, e a quanto pare ora siamo a $2069w. Il nostro numero magico è $2071w. Vuoi darci una mano?", "." },
